(31, 'Kuala Lumpur', 'City Centre (KLCC)', 'heritage', 'Kampung Baru', 'Traditional Malay enclave in central Kuala Lumpur known for heritage village atmosphere and local Malay food.', 'Jalan Raja Abdullah, Kampung Baru, 50300 Kuala Lumpur, Malaysia', 3.1630240, 101.7061401, 'Always open (public area)', NULL, NULL, 0.00, 0.00, 1, 'uploads/places/place_31_0beb0a3e93_20260114_152539_e627be.jpg', NULL, NULL, 90, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2026-01-14 07:09:09', '2026-04-25 17:44:50'),
(32, 'Penang', 'Timur Laut', 'heritage', 'Kek Lok Si Temple', 'One of the largest Buddhist temple complexes in Malaysia, located at Ayer Itam with pagoda and hilltop statue.', 'Jalan Balik Pulau, 11500 Ayer Itam, Penang, Malaysia', 5.4002200, 100.2738400, 'Daily 8:30 AM–5:30 PM', NULL, NULL, 0.00, 0.00, 1, 'uploads/places/place_1768401054_5697.jpg', NULL, NULL, 90, NULL, NULL, NULL, NULL, NULL, NULL, 1, NULL, '2026-01-14 07:09:09', '2026-04-25 17:44:50'),
